using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Xml.Serialization;

namespace MaohaiziPet {
public static class PetLifeTests {
    static LivingReport report;
    static readonly DateTime Day=new DateTime(2026,11,22,14,0,0);
    static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Check(string name,Action run){var result=new TestResult{name=name};try{run();result.passed=true;report.passed++;}catch(Exception e){result.error=e.Message;report.failed++;}report.tests.Add(result);}
    static PetLife New(){return new PetLife(new PetLifeRecord(),Day);}
    static void Save(BitmapSource image,string path){var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(path))png.Save(f);}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state-"+Guid.NewGuid().ToString("N")));report=new LivingReport{scope="QQ Pet-inspired original toy interaction, genuine local memories, preference, moods, persistence, interruption and tool hit regions"};
        Check("未发生的互动不会出现在小记里",delegate{var life=New();Assert(life.Record.Touches==0&&life.Record.Games==0&&life.Record.Treats==0&&life.Favorite==PetTouchZone.None,"凭空生成了历史");Assert(life.TodayNote=="今天也在这里，陪你慢慢过。"&&!life.Memories.Contains("已经有了第一次"),"编造互动回忆");});
        Check("持续同一处抚摸不刷次数，分开的相处会积累偏好",delegate{var life=New();for(int i=0;i<60;i++){life.Touch(PetTouchZone.Chin);life.Tick(.1,true,false,Day);}Assert(life.Record.Touches==1&&life.Record.TouchCounts[(int)PetTouchZone.Chin]==1,"短时间刷次数");for(int i=0;i<2;i++){life.Tick(16,true,false,Day);life.Touch(PetTouchZone.Chin);}Assert(life.Favorite==PetTouchZone.Chin&&life.Record.Touches==3&&life.FavoriteLabel.Contains("下巴"),"没有记住摸法");});
        Check("旧配置可添加相处记录并往返保留姓名位置和熟悉感",delegate{string xml="<PetSettings><Name>布偶猫</Name><Familiarity>33.5</Familiarity><Left>1346</Left><Top>488</Top></PetSettings>";var serializer=new XmlSerializer(typeof(PetSettings));PetSettings settings;using(var text=new StringReader(xml))settings=(PetSettings)serializer.Deserialize(text);var life=new PetLife(settings.Life,Day);life.Touch(PetTouchZone.Head);life.Game();life.Treat();settings.Life=life.Record;using(var bytes=new MemoryStream()){serializer.Serialize(bytes,settings);bytes.Position=0;var restored=(PetSettings)serializer.Deserialize(bytes);Assert(restored.Name=="布偶猫"&&restored.Familiarity==33.5&&restored.Left==1346&&restored.Top==488&&restored.Life.Games==1&&restored.Life.Touches==1,"升级持久化改变了原设置或丢失记录");}});
        Check("离开不惩罚关系，心情平静后仍保留真实回忆",delegate{var life=New();life.Touch(PetTouchZone.Head);life.Game();life.Tick(86400,false,false,Day.AddDays(1));Assert(life.Record.Touches==1&&life.Record.Games==1&&life.Mood==0&&life.Record.TogetherSeconds==0,"离开扣回忆或虚增陪伴时间");});
        Check("跨日小记分开记录，记录最多保留十四天",delegate{var life=New();for(int i=0;i<25;i++){life.Tick(20,false,false,Day.AddDays(i));life.Touch(PetTouchZone.Head);}Assert(life.Record.Days.Count==14&&life.Record.Days[0].Date=="2026-12-16"&&life.Record.Days[0].Touches==1,"跨日记录错误");});
        Check("零食有短暂停顿，不因快速连点虚增投喂",delegate{var life=New();Assert(life.Treat(),"第一次零食未记录");for(int i=0;i<30;i++){life.Tick(.1,true,false,Day);Assert(!life.Treat(),"快速投喂计数");}life.Tick(8,true,false,Day);Assert(life.Treat()&&life.Record.Treats==2,"正常间隔无法投喂");});
        Check("摸摸和玩耍产生不同心情，再自然回到平静",delegate{var life=New();life.Touch(PetTouchZone.Back);Assert(life.Mood==1&&life.MoodLabel.Contains("安心"),"摸摸心情错误");life.Game();Assert(life.Mood==2&&life.MoodLabel.Contains("开心"),"玩耍心情错误");life.Tick(90,true,false,Day);Assert(life.Mood==0,"情绪未自然归位");});
        Check("心情会影响后续动作选择，同时保留动作冷却",delegate{int calmPlay=0,happyPlay=0;foreach(int mood in new[]{0,2})for(int seed=0;seed<20;seed++){var h=new CatHabits(seed){GroomReady=true,YawnReady=true,SitReady=true,StandReady=true,SleepReady=true,Mood=mood};int revision=0;var last=new Dictionary<CatHabit,double>();for(int i=0;i<7200;i++){h.Tick(.25,PetMode.Companion,false,false);if(h.Revision==revision)continue;revision=h.Revision;if(last.ContainsKey(h.Current))Assert(h.Clock-last[h.Current]>=CatHabits.Cooldown(h.Current),"心情覆盖了动作冷却");last[h.Current]=h.Clock;if(h.Current==CatHabit.PawPlay){if(mood==0)calmPlay++;else happyPlay++;}}}Assert(happyPlay>calmPlay,"心情只改标签没有改变动作选择");});
        Check("羽毛静止不反复挥爪，远处摇晃也不凭空抓到",delegate{var play=new PetPlaySession();play.Select(PetTool.Feather);for(int i=0;i<120;i++){play.Tick(.05);play.Observe(new Point(106,214),true);}Assert(play.Swats==0,"静止玩具反复挥爪");for(int i=0;i<120;i++){play.Tick(.05);play.Observe(new Point(i%2==0?30:220,45),true);}Assert(play.Swats==0&&!play.CompletedGame,"抓到了爪子够不到的羽毛");});
        Check("移动羽毛到爪边触发对应爪，玩够三次只记一轮",delegate{var play=new PetPlaySession();play.Select(PetTool.Feather);int games=0;for(int i=0;i<500;i++){play.Tick(.05);if(play.Observe(new Point(106+Math.Sin(i*.4)*13,211),true))games++;}Assert(play.Swats>=3&&games==1,"没有真实互动或一轮被反复计数");var s=new CompanionSignals();play.Apply(s);Assert(s.PointerToy==1&&s.PointerPawRight==0,"左边羽毛触发错爪");});
        Check("右边羽毛有独立的右爪反馈",delegate{var play=new PetPlaySession();play.Select(PetTool.Feather);play.Observe(new Point(152,210),true);play.Tick(.2);play.Observe(new Point(170,210),true);play.Tick(.2);var signals=new CompanionSignals();play.Apply(signals);Assert(signals.PointerPawRight>.5&&signals.PointerPawLeft==0,"右边羽毛没有右爪反馈");});
        Check("玩具出界、放下和超时都会归位，不永久占用桌面",delegate{var play=new PetPlaySession();play.Select(PetTool.Feather);play.Observe(new Point(120,205),true);play.Observe(new Point(900,900),false);Assert(!play.PointerVisible,"出界还显示工具");play.Tick(46);var signals=new CompanionSignals();play.Apply(signals);Assert(!play.Active&&signals.PointerToy==0&&signals.PointerPawLeft==0&&signals.PointerPawRight==0,"超时后仍抓取指针");play.Select(PetTool.Brush);play.Stop();Assert(!play.Active,"手动放下失败");});
        Check("勿扰会放下工具，隐藏期间不记陪伴时长",delegate{var life=New();life.Play.Select(PetTool.Feather);life.Tick(5,false,true,Day);Assert(!life.Play.Active&&life.Record.TogetherSeconds==0,"勿扰或隐藏失效");});
        Check("熟悉的摸法增强回应，未学会前不凭空指定偏好",delegate{var life=New();var signals=new CompanionSignals{TouchChin=1};life.Apply(signals,PetTouchZone.Chin);Assert(signals.Nuzzle==0,"初见即有偏好");for(int i=0;i<3;i++){life.Tick(16,true,false,Day);life.Touch(PetTouchZone.Chin);}life.Apply(signals,PetTouchZone.Chin);Assert(signals.Nuzzle>.2,"记住偏好后回应没有变化");});
        Check("无效保存数据受控，日记不会无限增长",delegate{var record=new PetLifeRecord{TogetherSeconds=double.NaN,Touches=-5,TouchCounts=null,Days=null};var life=new PetLife(record,Day);Assert(life.Record.TogetherSeconds==0&&life.Record.Touches==0&&life.Record.TouchCounts.Length==10&&life.Record.Days.Count==0,"无效配置未规范");});
        var app=new Application();var controller=new PetController(app);controller.Settings.Name="布偶猫";controller.Skin=PetSkin.Load(manifest);controller.Pet=new PetWindow(controller);controller.Pet.Surface.Measure(new Size(360,300));controller.Pet.Surface.Arrange(new Rect(0,0,360,300));
        Check("工具范围只在猫旁边，默认恢复透明穿透",delegate{var surface=controller.Pet.Surface;Point nearby=new Point(surface.PetRect.Left-10,surface.PetRect.Top+20);Assert(!surface.HitPet(nearby),"默认空白被占用");controller.Life.Play.Select(PetTool.Feather);Assert(surface.HitPet(nearby)&&!surface.HitPet(new Point(2,2)),"工具范围越界");controller.Life.Play.Stop();Assert(!surface.HitPet(nearby),"放下后仍占用透明区域");});
        Check("羽毛位置真正驱动视线和爪子，起止连续",delegate{var rig=new LivingPet(controller.Skin.Frames[0],113,controller.Skin.Living.ModernTexture);var signals=new CompanionSignals{PointerToy=1,PointerToyX=-.8,PointerToyY=.7,PointerPawLeft=.9};double largest=0;for(int i=0;i<90;i++){double before=rig.Pose.HeadX;rig.Advance(1.0/60,PetAction.Idle,PetMode.Companion,null,signals);largest=Math.Max(largest,Math.Abs(rig.Pose.HeadX-before));}Assert(rig.Pose.GazeX<-.7&&rig.Pose.PawLeft>5&&largest<.3,"玩具没有真正驱动身体或出现硬切");});
        Check("相处小记界面能渲染并展示本地实际记录",delegate{controller.Life.Touch(PetTouchZone.Chin);controller.Life.Game();controller.Life.Treat();var window=new PetLifeWindow(controller);var content=(FrameworkElement)window.Content;content.Measure(new Size(500,560));content.Arrange(new Rect(0,0,500,560));content.UpdateLayout();var image=new RenderTargetBitmap(500,560,96,96,PixelFormats.Pbgra32);var backdrop=new DrawingVisual();using(var d=backdrop.RenderOpen())d.DrawRectangle(new SolidColorBrush(Color.FromRgb(245,243,236)),null,new Rect(0,0,500,560));image.Render(backdrop);image.Render(content);Save(image,Path.Combine(output,"memory-ui-review.png"));Assert(controller.Life.TodayNote.Contains("1 次")&&controller.Life.Record.Games==1,"界面数据源没有真实记录");window.Close();});
        controller.Dispose();controller.Pet.Close();
        using(var file=File.Create(Path.Combine(output,"life-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(file,report);return report.failed==0?0:1;
    }
}
}
